    for color in {v for row in grid for v in row if v!=grid[0][0]}:
        cells={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}
        for dr,dc in ((1,1),(1,-1)):
            for r,c in cells:
                if (r-dr,c-dc) in cells: continue
                run=[];rr,cc=r,c
                while (rr,cc) in cells:
                    run.append((rr,cc));rr+=dr;cc+=dc
                if len(run)<3: continue
                rr,cc=run[0][0]-dr,run[0][1]-dc
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==grid[0][0]:
                    out[rr][cc]=color;rr-=dr;cc-=dc
    return out
